// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivateBank, Log} from "../src/PrivateBank.sol";

contract Reverter {
    fallback() external payable { revert(); }
}

contract InvMutTest is Test {
    PrivateBank c;

    function setUp() public {
        c = new PrivateBank(address(new Log()));
    }

    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount, uint256 actorSeed) public {
        address actor = vm.addr(uint256(keccak256(abi.encodePacked(actorSeed))) | 1);

        depositAmount = bound(depositAmount, c.MinDeposit(), 100 ether);
        withdrawAmount = bound(withdrawAmount, 0, depositAmount);

        vm.deal(actor, depositAmount);
        vm.prank(actor);
        c.Deposit{value: depositAmount}();

        uint256 balBefore = c.balances(actor);
        assertEq(balBefore, depositAmount, "deposit failed to credit balance");

        // Withdraw exactly-balance amount. Reference succeeds and zeroes balance;
        // mutant (with `_am < balances[msg.sender]`) reverts.
        vm.prank(actor);
        bool ok = true;
        try c.CashOut(withdrawAmount) {
            ok = true;
        } catch {
            ok = false;
        }

        if (withdrawAmount == balBefore) {
            assertTrue(ok && c.balances(actor) == 0, "exact-balance withdrawal must succeed and zero balance");
        } else {
            assertTrue(ok && c.balances(actor) == balBefore - withdrawAmount, "withdrawal must succeed and decrement balance exactly");
        }
    }
}
